   Q('mcq', 'Why must traders open on at least four days a week?', 'B', 'empty stalls make the whole market look less lively', 'Empty stalls harm the atmosphere for all traders.', opts=['It is a condition of the royal charter.', 'Closed stalls make the market seem less busy.', 'Rent is calculated by the day.']),
